{{ (() => {
  const d = $json;
  const safe = value => String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

  const pulse = safe(d.weekly_pulse).replace(/\n/g, "<br>");

  const bullets = d.explanation_bullets
    .map(b => `<li>${safe(b)}</li>`)
    .join("");

  const links = d.source_links
    .map(u => `<li><a href="${safe(u)}">${safe(u)}</a></li>`)
    .join("");

  return `
    <h3>1. Weekly Product Pulse</h3>
    <p>${pulse}</p>
    <hr>
    <h3>2. Customer Support Fee Explainer</h3>
    <ul>${bullets}</ul>
    <h4>Official sources</h4>
    <ul>${links}</ul>
    <p><strong>Last checked:</strong> ${safe(d.last_checked)}</p>
    <p><strong>Note:</strong> Quotations pending human verification.</p>
  `;
})() }}

