// Runs ONLY on explicit Approve + "Quotes checked against originals" = Verified.
const form = $input.first().json;
if (form.Decision !== 'Approve' || form['Quotes checked against originals'] !== 'Verified') {
  throw new Error('Explicit approval and quotation verification required');
}

let d, rows, analysis;
try { d = $('Normalise and Check Draft').first().json; }
catch (_) { d = $('Use Cached Draft for Demo').first().json; }
try { rows = $('Get row(s) in sheet').all().map(i => i.json); }
catch (_) { rows = $('Get Reviews for Demo').all().map(i => i.json); }
try { analysis = $('Validate and Count 1000 Reviews').first().json; }
catch (_) { analysis = $('Use Cached Draft for Demo').first().json; }

if (rows.length !== 1000 || typeof d.weekly_pulse !== 'string' || !Array.isArray(d.explanation_bullets)) {
  throw new Error('Source review data or approved draft unavailable');
}

// Theme counts come from the analysis, never from literals in this node.
const themes = analysis && Array.isArray(analysis.top_themes) ? analysis.top_themes : null;
if (!themes || !themes.length) throw new Error('Theme counts unavailable; refusing to publish');

// T5 is a satisfaction baseline, not a product issue, so rank it separately.
const issueThemes = themes
  .filter(t => t.theme_id !== 'T5')
  .sort((a, b) => b.review_count - a.review_count)
  .slice(0, 3);
const baseline = themes.find(t => t.theme_id === 'T5') || null;
if (issueThemes.length !== 3) throw new Error('Expected three issue themes');

const candidates = [
  ['e6afdabd-5336-47bd-985c-a5302b699cdb', 'T2'],
  ['ec74a5f0-aa7c-4623-b74e-0bd8c04cc133', 'T3'],
  ['01d9c2da-575e-46b5-9e7a-d5ce3019a168', 'T1']
];

const checks = [];
for (const [id, theme] of candidates) {
  const matches = rows.filter(r => String(r.review_id) === id);
  if (matches.length !== 1) throw new Error('Missing or duplicate quote source ' + id);
  const r = matches[0];
  const text = String(r.cleaned_review_text ?? '');
  const safe = /^(yes|true)$/i.test(String(r.quote_eligible)) && /^(no|false)$/i.test(String(r.pii_redacted));
  // Conservative identifier check; a human still checks the original privately.
  const suspicious = /\d{7,}|[6-9]\d{4}[\s.-]*\d{5}|@|contact\s*(no|number)|ticket\s*(no|id)|\[REDACTED/i.test(text);
  if (!safe || suspicious || !text || !d.weekly_pulse.includes(text)) {
    throw new Error('Quote not eligible, safe or verbatim in pulse: ' + id);
  }
  checks.push({ review_id: id, theme_id: theme, matches_cleaned_source: true });
}

if (checks.length !== 3 || d.explanation_bullets.length > 6 ||
    d.weekly_pulse.trim().split(/\s+/).length > 250) {
  throw new Error('Report integrity error');
}

// The approver confirmed the quotes at this gate, so the published copy must
// not still describe them as pending. Swap the known marker; if some other
// pending-verification wording is present, refuse rather than publish a label
// that contradicts the approval that authorised this write.
const PENDING = /Customer quotes \(pending human verification\):/i;
let publishedPulse = d.weekly_pulse;
if (PENDING.test(publishedPulse)) {
  publishedPulse = publishedPulse.replace(
    PENDING, 'Customer quotes (verified against originals by approver):'
  );
} else if (/pending human verification/i.test(publishedPulse)) {
  throw new Error('Unrecognised pending-verification label; refusing to publish');
}

// Re-check the limit against the text that actually ships, not the draft.
if (publishedPulse.trim().split(/\s+/).length > 250) {
  throw new Error('Pulse exceeds 250 words after the verification relabel');
}

const payload = {
  date: new Date().toISOString().slice(0, 10),
  product: 'Groww',
  top_themes: issueThemes.map(t => ({
    theme_id: t.theme_id,
    label: t.label || t.theme_id,
    review_count: t.review_count
  })),
  satisfaction_baseline: baseline
    ? { theme_id: 'T5', review_count: baseline.review_count }
    : null,
  weekly_pulse: publishedPulse,
  identified_fee_issue: d.identified_fee_issue,
  explanation_bullets: d.explanation_bullets,
  source_links: d.source_links,
  last_checked: d.last_checked,
  sample_size: rows.length,
  quote_verification: 'verified_against_originals_by_approver',
  quote_checks: checks
};

return [{ json: {
  run_id: `groww_${$execution.id}`,
  payload_json: JSON.stringify(payload),
  status: 'approved',
  doc_status: 'pending',
  draft_status: 'pending',
  approved_at: new Date().toISOString()
} }];

// CACHED OUTPUT from a prior validated 1000-review run; NOT a fresh AI call.
// Theme counts travel with the draft so the demo path builds its payload
// from data rather than from literals in the payload-builder node.
const draft = {
  "product": "Groww",
  "weekly_pulse": "Covers 1,000 public Play Store reviews sampled 2026-08-11 to 2026-10-16, not only last week. Baseline: 814 of 1,000 (81%) carry no substantive complaint. Counts are complaint volume here, not shares of the customer base.\n\nTop issue themes: Technical Issues (T2: 73), Feature Requests (T4: 44), Poor Customer Support (T3: 28). High Fees (T1: 24) is the fee focus. Fee-topic labels total 25 against a T1 count of 24; the one-review discrepancy is flagged, not reconciled.\n\nCustomer quotes (pending human verification):\n- Technical (e6afdabd): \"Please fix this glitch. Most of the time, the stop-loss doesn’t get placed, and because of this, I end up taking losses.\"\n- Support (ec74a5f0): \"Worst customer service i am requesting a simple spelling change of my surname 1 month ago and still pending my name correction\"\n- Fees (01d9c2da): \"bakwas app hai inka charge bahut jyada hai koi fresher hai starting me kam share hi kharidega kharine pr 10 aur bechne pr 30\"\n\nKey observation: technical complaints concentrate on the order path - stop-loss not placing, hangs while ordering, login failure in market hours. Fee complaints are about asymmetry, not price level: the sell leg debits more than the buy leg and reads as a double charge.\n\nPM priorities:\n1. Order-path reliability: 73 reports, and failures block revenue during market hours.\n2. Charge transparency: a pre-trade buy/sell breakdown naming DP charges as sell-side removes the confusion.\n3. Non-trade support SLA: 28 reports; name and KYC fixes are cheap and reliably produce 1-star reviews.",
  "identified_fee_issue": "25 of 1000 sampled reviews mention charges, and 19 of those are rated 3 stars or below. Users are not disputing the price level. They are confused by the asymmetry between buy-side and sell-side charges, and read the larger sell-side debit as being charged twice. DP charges are levied only when shares leave the demat account, so they apply on sell transactions and not on buys; stamp duty applies on the buy side only. The sell leg therefore normally costs more than a comparable buy leg.",
  "explanation_bullets": [
    "Equity brokerage is ₹20 or 0.1% of the executed order value, whichever is lower, subject to a ₹5 minimum per executed order. This applies to both buy and sell orders.",
    "DP (depository) charges apply only when shares leave your demat account — that is, on sell transactions only. They are charged per sell transaction, not per share, so selling 5 shares and 500 shares of the same stock carry the same DP charge.",
    "Current DP charges are ₹3.5 per sell transaction to the depository (₹3.25 for women) plus ₹16.5 to Groww. The Groww component is ₹0 when the sell value is under ₹100.",
    "This is the usual reason a sell leg costs more than a comparable buy leg: DP charges apply on the sell side only, while stamp duty applies on the buy side only. It is one charge per leg, not the same charge applied twice.",
    "Statutory charges differ by side. On delivery trades, STT is 0.1% on both buy and sell; stamp duty is 0.015% on the buy side only; exchange transaction and SEBI turnover charges apply to both sides.",
    "18% GST applies to brokerage, DP charges, exchange transaction charges and SEBI turnover charges. It does not apply to STT or stamp duty. The exact amounts for any single trade are itemised in that trade's contract note."
  ],
  "source_links": [
    "https://groww.in/pricing",
    "https://groww.in/help/stocks/searchable/when-are-dp-charges-levied"
  ],
  "last_checked": "2026-10-18",
  "top_themes": [
    {
      "theme_id": "T5",
      "label": "General Satisfaction",
      "review_count": 814
    },
    {
      "theme_id": "T2",
      "label": "Technical Issues",
      "review_count": 73
    },
    {
      "theme_id": "T4",
      "label": "Feature Requests",
      "review_count": 44
    },
    {
      "theme_id": "T3",
      "label": "Poor Customer Support",
      "review_count": 28
    },
    {
      "theme_id": "T1",
      "label": "High Fees",
      "review_count": 24
    }
  ],
  "quote_verification_pending": true,
  "approval_status": "pending"
};
if ($input.all().length !== 1000) throw new Error('Expected 1000 source reviews');
return [{ json: draft }];
